/**
 * Lấy toàn bộ lịch sử tập luyện của một bài tập cụ thể
 */
export interface ExerciseSessionHistory {
  date: string;
  formattedDate: string;
  totalVolumeKg: number;
  sets: {
    setIndex: number;
    weightKg: number;
    reps: number;
    isWarmup: boolean;
  }[];
}

export function getExerciseHistorySessions(
  exerciseId: string, 
  exerciseName?: string,
  rawLogsOverride?: FitbodRawLogEntry[]
): {
  summary: {
    maxWeight: number;
    maxE1RM: number;
    bestSet: string;
    totalSets: number;
    totalSessions: number;
    lastDate: string;
    isAssisted: boolean;
  } | null;
  sessions: ExerciseSessionHistory[];
} {
  const logs: FitbodRawLogEntry[] = (rawLogsOverride && rawLogsOverride.length > 0 
    ? rawLogsOverride 
    : (DEFAULT_FITBOD_STATS.rawLogs || []));

  const targetId = exerciseId.toLowerCase().trim();
  const targetName = exerciseName ? exerciseName.toLowerCase().replace(/[^a-zA-Z0-9]/g, ' ').trim() : '';
  const isAssisted = !!(targetId.includes('assisted') || (targetName && targetName.includes('assisted')));

  // Lọc các hiệp của bài tập này
  const matchedLogs = logs.filter(log => {
    const logExId = (log as any).exerciseId ? String((log as any).exerciseId).toLowerCase().trim() : '';
    if (logExId && logExId === targetId) return true;

    const logNameClean = log.exercise.toLowerCase().replace(/[^a-zA-Z0-9]/g, ' ').trim();
    if (targetName && (logNameClean === targetName || logNameClean.includes(targetName) || targetName.includes(logNameClean))) {
      return true;
    }
    return false;
  });

  if (matchedLogs.length === 0) {
    return { summary: null, sessions: [] };
  }

  // Nhóm theo ngày (Session)
  const sessionMap: Record<string, {
    date: string;
    sets: { setIndex: number; weightKg: number; reps: number; isWarmup: boolean }[];
    volume: number;
  }> = {};

  let maxWeight = isAssisted ? -9999 : 0;
  let maxE1RM = 0;
  let bestSet = '';
  let lastDate = '';

  matchedLogs.forEach((log) => {
    const dateKey = log.date.substring(0, 10);
    if (!sessionMap[dateKey]) {
      sessionMap[dateKey] = {
        date: dateKey,
        sets: [],
        volume: 0
      };
    }

    // Chuẩn hóa trọng lượng bài Assisted: luôn là số âm (-kg)
    const normalizedWeight = (isAssisted && log.weightKg !== 0) 
      ? -Math.abs(log.weightKg) 
      : log.weightKg;

    const setIdx = sessionMap[dateKey].sets.length + 1;
    sessionMap[dateKey].sets.push({
      setIndex: setIdx,
      weightKg: normalizedWeight,
      reps: log.reps,
      isWarmup: !!log.isWarmup
    });

    if (!log.isWarmup && log.reps > 0) {
      if (isAssisted) {
        // Lực nâng tự thân = 68kg - Trợ lực
        const assistanceKg = Math.abs(normalizedWeight);
        const effectiveLift = Math.max(5, 68 - assistanceKg);
        sessionMap[dateKey].volume += effectiveLift * log.reps;
        const e1rm = log.reps < 37 
          ? Math.round((effectiveLift * 36 / (37 - log.reps)) * 10) / 10 
          : effectiveLift;

        if (e1rm > maxE1RM) {
          maxE1RM = e1rm;
          bestSet = `${log.reps} reps @ ${normalizedWeight}kg`;
        }
        // Với bài assisted, maxWeight là mức trợ lực ít nhất (số âm lớn nhất, ví dụ -30kg > -60kg)
        if (maxWeight === -9999 || normalizedWeight > maxWeight) {
          maxWeight = normalizedWeight;
        }
      } else if (normalizedWeight > 0) {
        sessionMap[dateKey].volume += normalizedWeight * log.reps;
        const e1rm = log.reps < 37 
          ? Math.round((normalizedWeight * 36 / (37 - log.reps)) * 10) / 10 
          : normalizedWeight;

        if (e1rm > maxE1RM) {
          maxE1RM = e1rm;
          maxWeight = Math.max(maxWeight, normalizedWeight);
          bestSet = `${log.reps} reps @ ${normalizedWeight}kg`;
        } else if (normalizedWeight > maxWeight) {
          maxWeight = normalizedWeight;
        }
      }
    }

    if (!lastDate || dateKey > lastDate) {
      lastDate = dateKey;
    }
  });

  if (isAssisted && maxWeight === -9999) {
    maxWeight = 0;
  }

  // Sắp xếp các buổi tập từ mới nhất đến cũ nhất
  const sessions: ExerciseSessionHistory[] = Object.values(sessionMap)
    .sort((a, b) => b.date.localeCompare(a.date))
    .map(s => {
      const d = new Date(s.date);
      const formattedDate = !isNaN(d.getTime()) 
        ? d.toLocaleDateString('vi-VN', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' })
        : s.date;

      return {
        date: s.date,
        formattedDate,
        totalVolumeKg: Math.round(s.volume * 10) / 10,
        sets: s.sets
      };
    });

  return {
    summary: {
      maxWeight,
      maxE1RM,
      bestSet: bestSet || `${matchedLogs[0].reps} reps @ ${matchedLogs[0].weightKg}kg`,
      totalSets: matchedLogs.length,
      totalSessions: sessions.length,
      lastDate,
      isAssisted
    },
    sessions
  };
}
